const a=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
if(a.some(x=>x.error))return [{json:{crmReadable:false,campaignCount:0,activeCount:0,reason:'ESPOCRM_LIST_UNAVAILABLE'}}];
const ids=new Set();
for(const c of a){if(typeof c.id!=='string'||!c.id||ids.has(c.id))throw Error('CRM_DUPLICATE_OR_INVALID_ID');ids.add(c.id);}
return [{json:{crmReadable:true,campaignCount:a.length,activeCount:a.filter(x=>x.status==='Active').length,
chatwootConfiguredCount:a.filter(x=>String(x.ageProvider||'').includes('Chatwoot')).length}}];

const a=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
if(a.some(x=>x.error))return [{json:{chatwootReadable:false,reason:'CHATWOOT_LIST_UNAVAILABLE'}}];
const counts={total:a.length,oneOffWhatsApp:0,processing:0,completed:0};const ids=new Set();
for(const c of a){const id=Number(c.id);if(!Number.isSafeInteger(id)||id<1||ids.has(id))throw Error('CHATWOOT_DUPLICATE_OR_INVALID_ID');ids.add(id);
 if(c.campaign_type==='one_off'&&c.inbox?.channel_type==='Channel::Whatsapp'){counts.oneOffWhatsApp++;if(c.campaign_status==='processing')counts.processing++;if(c.campaign_status==='completed')counts.completed++;}}
return [{json:{chatwootReadable:true,counts}}];

const espo=$('Count Espo Campaigns Without Eligibility Claims').first().json;
const chatwoot=$('Count Provider Batches Without Joining Names').first().json;
const portfolioRows=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
const blocks=[];
if(!espo.crmReadable)blocks.push('ESPOCRM_NOT_READABLE');
if(!chatwoot.chatwootReadable)blocks.push('CHATWOOT_NOT_READABLE');
if(!portfolioRows.length)blocks.push('PORTFOLIO_NOT_CONFIGURED');
if(portfolioRows.some(x=>x.error))blocks.push('POSTGRES_CONTROL_LEDGER_NOT_ACCESSIBLE');
const portfolio=portfolioRows.filter(x=>x.portfolio_id).map(x=>({
 portfolioId:x.portfolio_id,reason:x.reason,conservativeHeadroom:Number(x.conservative_headroom)||0,activeCycleId:x.active_cycle_id}));
for(const p of portfolio)if(p.reason!=='READY_FOR_OTHER_PRECHECKS')blocks.push(p.portfolioId+':'+p.reason);
blocks.push('RECIPIENT_POLICY_AND_CONSENT_NOT_PROVEN','BATCH_LABEL_SNAPSHOT_NOT_PROVEN','META_EXTERNAL_CAPACITY_AND_PROVIDER_RECEIPTS_NOT_PROVEN');
return [{json:{checkedAt:new Date().toISOString(),mode:'DRY_RUN',decision:'HOLD',reasons:[...new Set(blocks)],
 espoCRM:{campaigns:espo.campaignCount,activeCampaigns:espo.activeCount,chatwootConfigured:espo.chatwootConfiguredCount},
 chatwoot:chatwoot.counts??null,portfolio,canSend:false,createdCampaigns:0,
 crmEventsWritten:0,liveApprovalBypassed:false}}];
